///
///\file
///Thisfiledefinestheilist_nodeclasstemplate,whichisaconvenient
///baseclassforcreatingclassesthatcanbeusedwithilists.
///
//===----------------------------------------------------------------------===//

#ifndefLLVM_ADT_ILIST_NODE_H
#defineLLVM_ADT_ILIST_NODE_H

#include"llvm/ADT/ilist_node_base.h"
#include"llvm/ADT/ilist_node_options.h"

namespacellvm{

namespaceilist_detail{

structNodeAccess;

///Mixinbaseclassthatisusedtoadd\agetParent()and
///\asetParent(ParentTy*)methodsto\ailist_node_impliff\ailist_parent
///hasbeensetinthelistoptions.
template<classNodeTy,classParentTy>classnode_parent_access{
public:
inlineconstParentTy*getParent()const{
returnstatic_cast<constNodeTy*>(this)->getNodeBaseParent();
}
inlineParentTy*getParent(){
returnstatic_cast<NodeTy*>(this)->getNodeBaseParent();
}
voidsetParent(ParentTy*Parent){
returnstatic_cast<NodeTy*>(this)->setNodeBaseParent(Parent);
}
};
template<classNodeTy>classnode_parent_access<NodeTy,void>{};

}//endnamespaceilist_detail

template<classOptionsT,boolIsReverse,boolIsConst>classilist_iterator;
template<classOptionsT,boolIsReverse,boolIsConst>
classilist_iterator_w_bits;
template<classOptionsT>classilist_sentinel;

//Selectorforwhichiteratortypetopickgiventheiterator-bitsnodeoption.
template<booluse_iterator_bits,typenameOpts,boolarg1,boolarg2>
classilist_select_iterator_type{
public:
usingtype=ilist_iterator<Opts,arg1,arg2>;
};
template<typenameOpts,boolarg1,boolarg2>
classilist_select_iterator_type<true,Opts,arg1,arg2>{
public:
usingtype=ilist_iterator_w_bits<Opts,arg1,arg2>;
};

///Implementationforanilistnode.
///
///Templatedonanappropriate\ailist_detail::node_options,usuallycomputed
///by\ailist_detail::compute_node_options.
///
///Thisisawrapperaround\ailist_node_basewhosemainpurposeisto
///providetypesafety:youcan'tinsertnodesof\ailist_node_implintothe
///wrong\asimple_ilistor\aiplist.
template<classOptionsT>
classilist_node_impl
:OptionsT::node_base_type,
publicilist_detail::node_parent_access<ilist_node_impl<OptionsT>,
typenameOptionsT::parent_ty>{
usingvalue_type=typenameOptionsT::value_type;
usingnode_base_type=typenameOptionsT::node_base_type;
usinglist_base_type=typenameOptionsT::list_base_type;

friendtypenameOptionsT::list_base_type;
friendstructilist_detail::NodeAccess;
friendclassilist_sentinel<OptionsT>;

friendclassilist_detail::node_parent_access<ilist_node_impl<OptionsT>,
typenameOptionsT::parent_ty>;
friendclassilist_iterator<OptionsT,false,false>;
friendclassilist_iterator<OptionsT,false,true>;
friendclassilist_iterator<OptionsT,true,false>;
friendclassilist_iterator<OptionsT,true,true>;
friendclassilist_iterator_w_bits<OptionsT,false,false>;
friendclassilist_iterator_w_bits<OptionsT,false,true>;
friendclassilist_iterator_w_bits<OptionsT,true,false>;
friendclassilist_iterator_w_bits<OptionsT,true,true>;

protected:
usingself_iterator=
typenameilist_select_iterator_type<OptionsT::has_iterator_bits,OptionsT,
false,false>::type;
usingconst_self_iterator=
typenameilist_select_iterator_type<OptionsT::has_iterator_bits,OptionsT,
false,true>::type;
usingreverse_self_iterator=
typenameilist_select_iterator_type<OptionsT::has_iterator_bits,OptionsT,
true,false>::type;
usingconst_reverse_self_iterator=
typenameilist_select_iterator_type<OptionsT::has_iterator_bits,OptionsT,
true,true>::type;

ilist_node_impl()=default;

private:
ilist_node_impl*getPrev(){
returnstatic_cast<ilist_node_impl*>(node_base_type::getPrev());
}

ilist_node_impl*getNext(){
returnstatic_cast<ilist_node_impl*>(node_base_type::getNext());
}

constilist_node_impl*getPrev()const{
returnstatic_cast<ilist_node_impl*>(node_base_type::getPrev());
}

constilist_node_impl*getNext()const{
returnstatic_cast<ilist_node_impl*>(node_base_type::getNext());
}

voidsetPrev(ilist_node_impl*N){node_base_type::setPrev(N);}
voidsetNext(ilist_node_impl*N){node_base_type::setNext(N);}

public:
self_iteratorgetIterator(){returnself_iterator(*this);}
const_self_iteratorgetIterator()const{returnconst_self_iterator(*this);}

reverse_self_iteratorgetReverseIterator(){
returnreverse_self_iterator(*this);
}

const_reverse_self_iteratorgetReverseIterator()const{
returnconst_reverse_self_iterator(*this);
}

//Under-approximation,butalwaysavailableforassertions.
usingnode_base_type::isKnownSentinel;

///Checkwhetherthisisthesentinelnode.
///
///Thisrequiressentineltrackingtobeexplicitlyenabled.Usethe
///ilist_sentinel_tracking<true>optiontogetthisAPI.
boolisSentinel()const{
static_assert(OptionsT::is_sentinel_tracking_explicit,
"Useilist_sentinel_tracking<true>toenableisSentinel()");
returnnode_base_type::isSentinel();
}
};

///Anintrusivelistnode.
///
///Abaseclasstoenablemembershipinintrusivelists,including\a
///simple_ilist,\aiplist,and\ailist.Thefirsttemplateparameteristhe
///\avalue_typeforthelist.
///
///Anilistnodecanbeconfiguredwithcompile-timeoptionstochange
///behaviourand/oraddAPI.
///
///Bydefault,an\ailist_nodeknowswhetheritisthelistsentinel(an
///instanceof\ailist_sentinel)ifandonlyif
///LLVM_ENABLE_ABI_BREAKING_CHECKS.Thefunction\aisKnownSentinel()always
///returns\cfalsetrackingisoff.Sentineltrackingstealsabitfromthe
///"prev"link,whichaddsamaskoperationwhendecrementinganiterator,but
///enablesbug-findingassertionsin\ailist_iterator.
///
///Toturnsentineltrackingonallthetime,passinthe
///ilist_sentinel_tracking<true>templateparameter.Thisalsoenablesthe\a
///isSentinel()function.Thesameoptionmustbepassedtotheintrusive
///list.(ilist_sentinel_tracking<false>turnssentineltrackingoffallthe
///time.)
///
///Atypecaninheritfromilist_nodemultipletimesbypassingindifferent
///\ailist_tagoptions.Thisallowsasingleinstancetobeinsertedinto
///multiplelistssimultaneously,whereeachlistisgiventhesametag.
///
///\example
///structA{};
///structB{};
///structN:ilist_node<N,ilist_tag<A>>,ilist_node<N,ilist_tag<B>>{};
///
///voidfoo(){
///simple_ilist<N,ilist_tag<A>>ListA;
///simple_ilist<N,ilist_tag<B>>ListB;
///NN1;
///ListA.push_back(N1);
///ListB.push_back(N1);
///}
///\endexample
///
///Whenthe\ailist_parent<ParentTy>optionispassedtoanilist_nodeandthe
///owningilist,eachnodecontainsapointertotheilist'sowner.Thisadds
///\agetParent()and\asetParent(ParentTy*)methodstotheilist_node,which
///willbeusedfornodeaccessbytheilistifthenodeclasspublicly
///inheritsfrom\ailist_node_with_parent.Bydefault,setParent()isnot
///automaticallycalledbytheilist;aSymbolTableListwillcallsetParent()
///oninsertednodes,butthesentinelmuststillbemanuallysetafterthe
///listiscreated(e.g.SymTabList.end()->setParent(Parent)).
///
///Theprimarybenefitofusingilist_parentisthataparent
///pointerwillbestoredinthesentinel,meaningthatyoucansafelyuse\a
///ilist_iterator::getNodeParent()togetthenodeparentfromanyvalid(i.e.
///non-null)iterator,evenonethatpointstoasentinelvalue.
///
///See\ais_valid_optionforstepsonaddinganewoption.
template<classT,class...Options>
classilist_node
:publicilist_node_impl<
typenameilist_detail::compute_node_options<T,Options...>::type>{
static_assert(ilist_detail::check_options<Options...>::value,
"Unrecognizednodeoption!");
};

namespaceilist_detail{

///Anaccessclassforilist_nodeprivateAPI.
///
///Thisgivesaccesstotheprivatepartsofilistnodes.Nodesforanilist
///shouldfriendthisclassiftheyinheritprivatelyfromilist_node.
///
///Usingthisclassoutsideoftheilistimplementationisunsupported.
structNodeAccess{
protected:
template<classOptionsT>
staticilist_node_impl<OptionsT>*getNodePtr(typenameOptionsT::pointerN){
returnN;
}

template<classOptionsT>
staticconstilist_node_impl<OptionsT>*
getNodePtr(typenameOptionsT::const_pointerN){
returnN;
}

template<classOptionsT>
statictypenameOptionsT::pointergetValuePtr(ilist_node_impl<OptionsT>*N){
returnstatic_cast<typenameOptionsT::pointer>(N);
}

template<classOptionsT>
statictypenameOptionsT::const_pointer
getValuePtr(constilist_node_impl<OptionsT>*N){
returnstatic_cast<typenameOptionsT::const_pointer>(N);
}

template<classOptionsT>
staticilist_node_impl<OptionsT>*getPrev(ilist_node_impl<OptionsT>&N){
returnN.getPrev();
}

template<classOptionsT>
staticilist_node_impl<OptionsT>*getNext(ilist_node_impl<OptionsT>&N){
returnN.getNext();
}

template<classOptionsT>
staticconstilist_node_impl<OptionsT>*
getPrev(constilist_node_impl<OptionsT>&N){
returnN.getPrev();
}

template<classOptionsT>
staticconstilist_node_impl<OptionsT>*
getNext(constilist_node_impl<OptionsT>&N){
returnN.getNext();
}
};

template<classOptionsT>structSpecificNodeAccess:NodeAccess{
protected:
usingpointer=typenameOptionsT::pointer;
usingconst_pointer=typenameOptionsT::const_pointer;
usingnode_type=ilist_node_impl<OptionsT>;

staticnode_type*getNodePtr(pointerN){
returnNodeAccess::getNodePtr<OptionsT>(N);
}

staticconstnode_type*getNodePtr(const_pointerN){
returnNodeAccess::getNodePtr<OptionsT>(N);
}

staticpointergetValuePtr(node_type*N){
returnNodeAccess::getValuePtr<OptionsT>(N);
}

staticconst_pointergetValuePtr(constnode_type*N){
returnNodeAccess::getValuePtr<OptionsT>(N);
}
};

}//endnamespaceilist_detail

template<classOptionsT>
classilist_sentinel:publicilist_node_impl<OptionsT>{
public:
ilist_sentinel(){
this->initializeSentinel();
reset();
}

voidreset(){
this->setPrev(this);
this->setNext(this);
}

boolempty()const{returnthis==this->getPrev();}
};

///Anilistnodethatcanaccessitsparentlist.
///
///Requires\cNodeTytohave\agetParent()tofindtheparentnode,andthe
///\cParentTytohave\agetSublistAccess()togetareferencetothelist.
template<typenameNodeTy,typenameParentTy,class...Options>
classilist_node_with_parent:publicilist_node<NodeTy,Options...>{
protected:
ilist_node_with_parent()=default;

private:
///ForwardtoNodeTy::getParent().
///
///Note:donotusethename"getParent()".Wewantacompileerror
///(insteadofrecursion)whenthesubclassfailstoimplement\a
///getParent().
constParentTy*getNodeParent()const{
returnstatic_cast<constNodeTy*>(this)->getParent();
}

public:
///@nameAdjacentNodeAccessors
///@{
///Getthepreviousnode,or\cnullptrforthelisthead.
NodeTy*getPrevNode(){
//Shouldbeseparatedtoareusedfunction,butthenwecouldn'tuseauto
//(andwouldneedthetypeofthelist).
constauto&List=
getNodeParent()->*(ParentTy::getSublistAccess((NodeTy*)nullptr));
returnList.getPrevNode(*static_cast<NodeTy*>(this));
}

///Getthepreviousnode,or\cnullptrforthelisthead.
constNodeTy*getPrevNode()const{
returnconst_cast<ilist_node_with_parent*>(this)->getPrevNode();
}

///Getthenextnode,or\cnullptrforthelisttail.
NodeTy*getNextNode(){
//Shouldbeseparatedtoareusedfunction,butthenwecouldn'tuseauto
//(andwouldneedthetypeofthelist).
constauto&List=
getNodeParent()->*(ParentTy::getSublistAccess((NodeTy*)nullptr));
returnList.getNextNode(*static_cast<NodeTy*>(this));
}

///Getthenextnode,or\cnullptrforthelisttail.
constNodeTy*getNextNode()const{
returnconst_cast<ilist_node_with_parent*>(this)->getNextNode();
}
///@}
};

}//endnamespacellvm

#endif//LLVM_ADT_ILIST_NODE_H
